import{_ as t,o as r,c as a,l as n,t as s,N as i}from"./chunks/framework.CMqbtke2.js";const u=JSON.parse('{"title":"thread-keyring | x-cmd man (man7) | per-thread keyring","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | thread-keyring - per-thread keyring","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"thread-keyring | x-cmd man (man7) | per-thread keyring"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | thread-keyring - per-thread keyring"}]]},"headers":[],"params":{"isMan":true,"man":"thread-keyring","category":"man7","desc":"per-thread keyring"},"relativePath":"man7/thread-keyring.md","filePath":"man7/thread-keyring.md"}'),o={name:"man7/thread-keyring.md"},d={class:"visually-hidden"},h=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>thread-keyring - per-thread keyring</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The thread keyring is a keyring used to anchor keys on behalf of a process. It is created only when a thread requests it. The thread keyring has the name (description) <em>_tid</em>.</p><p>A special serial number value, <strong>KEY_SPEC_THREAD_KEYRING</strong>, is defined that can be used in lieu of the actual serial number of the calling thread&#39;s thread keyring.</p><p>From the <strong>keyctl</strong>(1) utility, &#39;<strong>@t</strong>&#39; can be used instead of a numeric key ID in much the same way, but as <strong>keyctl</strong>(1) is a program run after forking, this is of no utility.</p><p>Thread keyrings are not inherited across <strong>clone</strong>(2) and <strong>fork</strong>(2) and are cleared by <strong>execve</strong>(2). A thread keyring is destroyed when the thread that refers to it terminates.</p><p>Initially, a thread does not have a thread keyring. If a thread doesn&#39;t have a thread keyring when it is accessed, then it will be created if it is to be modified; otherwise the operation fails with the error <strong>ENOKEY</strong>.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>keyctl</strong>(1), <strong>keyctl</strong>(3), <strong>keyrings</strong>(7), <strong>persistent-keyring</strong>(7), <strong>process-keyring</strong>(7), <strong>session-keyring</strong>(7), <strong>user-keyring</strong>(7), <strong>user-session-keyring</strong>(7)</p>',10);function g(e,c,l,m,p,y){return r(),a("div",null,[n("h1",d,s(e.$params.man),1),h])}const _=t(o,[["render",g]]);export{u as __pageData,_ as default};
